from pathlib import Path
import sys
import unittest
from copy import deepcopy

ROOT = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(ROOT / '2-MOTORES' / 'OTIMIZADOR'))
from fila_local_v1 import PacoteLocalV1, FalhaPacoteLocal
from fila_producao_v3 import FORMULA_APROVADA, MOTOR_VERSAO


class PacoteVoltaMarcar(unittest.TestCase):
    def pacote(self, bloqueios):
        p = object.__new__(PacoteLocalV1)
        p.manifesto = dict(contrato='otimizador_pacote_local_v2', versao_pacote=2,
            lote_id='teste-sem-execucao', formula_fingerprint=FORMULA_APROVADA,
            motor_versao=MOTOR_VERSAO, pode_publicar=False,
            impetos_condicionais='nenhum_no_lote',
            regua={'gate': {'pode_rodar': True}, 'politica_habilidades': {'versao':'habilidades-funcao-20260909-v1'}, 'bloqueios': bloqueios})
        return p

    def test_rejeita_fotografia_antiga(self):
        with self.assertRaisesRegex(FalhaPacoteLocal, 'Volta para marcar'):
            self.pacote([])._validar_manifesto()

    def test_exige_cada_especialidade_aprovada(self):
        ids = [1, 2, 6, 7, 10, 11, 16, 17, 18, 19]
        for ausente in ids:
            with self.subTest(ausente=ausente):
                with self.assertRaises(FalhaPacoteLocal):
                    self.pacote([{'skill_id': 56, 'funcao_id': i}
                                 for i in ids if i != ausente])._validar_manifesto()

